  void _navigateToTab(int index) {
    if (index < 0 || index >= 24) return;
    setState(() {
      _tab = index;
      if (index == 1) {
        _vendorSubTab = 0;
        final firstDirIdx = _vendors.indexWhere((v) => v['isLocked'] != true);
        _selectedVendorIdx = firstDirIdx != -1 ? firstDirIdx : 0;
      }
      if (index == 6) {
        _hasInitialCenteredLiveTracking = true;
        _centerLiveTrackingMapOnFirstRider();
      }
      if (index == 16) {
        for (var o in [..._customerOrders, ..._customerOrderHistory]) {
          final id = (o['_id'] ?? o['id'] ?? '').toString();
          if (id.isNotEmpty) _seenShopPayoutOrderIds.add(id);
        }
      }
    });
    _fetchDataForTab(index);
  }

  void _selectTab(int index, String label) {
    if (_tab == index) return;
    setState(() {
      _tab = index;
      if (label == 'Vendors' || index == 1) {
        _vendorSubTab = 0;
        final firstOnlineIdx = _vendors.indexWhere((v) => (v['approvalStatus'] == 'approved' || v['status'] == 'approved') && (v['isOpen'] == true || v['isOnline'] == true) && v['isLocked'] != true);
        _selectedVendorIdx = firstOnlineIdx;
        for (var pv in _pendingVendors) {
          final id = (pv['_id'] ?? pv['id'] ?? '').toString();
          if (id.isNotEmpty) _seenPendingVendorIds.add(id);
        }
      }
      if (index == 6) {
        _hasInitialCenteredLiveTracking = true;
        _centerLiveTrackingMapOnFirstRider();
      }
      if (label == 'Shop Quotes & Payments' || index == 16) {
        for (var o in [..._customerOrders, ..._customerOrderHistory]) {
          final id = (o['_id'] ?? o['id'] ?? '').toString();
          if (id.isNotEmpty) _seenShopPayoutOrderIds.add(id);
        }
      }
    });
    _fetchDataForTab(index);
  }

  void _fetchDataForTab(int tabIndex) {
    switch (tabIndex) {
      case 0:
        _fetchFinancialStats(silent: _financialSummary != null);
        _fetchPerformanceAnalytics(silent: _topVendors.isNotEmpty);
        _fetchExpiringVendors(silent: true);
        _fetchOfflineVendors(silent: true);
        if (_reportSummary.isEmpty) _fetchReportData(silent: true);
        if (_adminReviewsList.isEmpty) _fetchAdminReviews(silent: true);
        if (_packingHistoryList.isEmpty) _fetchPackingHistory(silent: true);
        break;
      case 1:
        _fetchAllVendors(silent: _vendors.isNotEmpty);
        _fetchPendingVendors(silent: true);
        _fetchExpiringVendors(silent: true);
        _fetchOfflineVendors(silent: true);
        break;
      case 2:
        _fetchAllAdmins(silent: _admins.isNotEmpty);
        break;
      case 3:
        _fetchAllDrivers(silent: _allDrivers.isNotEmpty);
        _fetchAvailableDrivers(silent: true);
        _fetchPendingDrivers(silent: true);
        break;
      case 5:
        _fetchDispatchOrders(silent: _dispatchOrders.isNotEmpty);
        _fetchAvailableDrivers(silent: true);
        break;
      case 6:
        _fetchAvailableDrivers(silent: _onlineDrivers.isNotEmpty);
        break;
      case 7:
        _fetchCustomerOrders(silent: _customerOrders.isNotEmpty);
        _fetchCustomerOrderHistory(silent: true);
        break;
      case 8:
        _fetchAllCustomers(silent: _customers.isNotEmpty);
        break;
      case 10:
        _fetchSupportTickets(silent: _supportTickets.isNotEmpty);
        break;
      case 11:
        _fetchHeatmapData(silent: _heatmapOrdersList.isNotEmpty);
        break;
      case 12:
        _fetchAuditLogs(silent: _auditLogs.isNotEmpty);
        _fetchAuditStats();
        break;
      case 13:
        _fetchReportData(silent: _reportSummary.isNotEmpty);
        break;
      case 14:
        _fetchSettings();
        if (_exclusionZones == null) _fetchServiceZones(silent: true);
        break;
      case 15:
        _fetchSubscriptionPlans(silent: _subscriptionPlans.isNotEmpty);
        break;
      case 16:
      case 17:
      case 18:
      case 23:
        _fetchCustomerOrders(silent: _customerOrders.isNotEmpty);
        if (_customerOrderHistory.isEmpty) _fetchCustomerOrderHistory(silent: true);
        break;
      case 19:
        _fetchFinancialStats(silent: _financialSummary != null);
        break;
      case 20:
        _fetchFailedPayments(silent: _failedPayments.isNotEmpty);
        break;
      default:
        break;
    }
  }

  void _syncActiveTab() {
    if (!mounted) return;
    switch (_tab) {
      case 0:
        _fetchFinancialStats(silent: true);
        _fetchPerformanceAnalytics(silent: true);
        _fetchExpiringVendors(silent: true);
        _fetchOfflineVendors(silent: true);
        break;
      case 1:
        _fetchPendingVendors(silent: true);
        _fetchAllVendors(silent: true);
        _fetchExpiringVendors(silent: true);
        _fetchOfflineVendors(silent: true);
        break;
      case 2:
        _fetchAllAdmins(silent: true);
        break;
      case 3:
        _fetchAvailableDrivers(silent: true);
        _fetchPendingDrivers(silent: true);
        _fetchAllDrivers(silent: true);
        break;
      case 5:
        _fetchDispatchOrders(silent: true);
        _fetchAvailableDrivers(silent: true);
        break;
      case 6:
        _fetchAvailableDrivers(silent: true);
        break;
      case 7:
      case 16:
      case 17:
      case 18:
      case 23:
        _fetchCustomerOrders(silent: true);
        _fetchCustomerOrderHistory(silent: true);
        break;
      case 8:
        _fetchAllCustomers(silent: true);
        break;
      case 10:
        _fetchSupportTickets(silent: true);
        break;
      case 12:
        _fetchAuditLogs(silent: true);
        _fetchAuditStats();
        break;
      case 13:
        _fetchReportData(silent: true);
        break;
      case 15:
        _fetchSubscriptionPlans(silent: true);
        break;
      case 19:
        _fetchFinancialStats(silent: true);
        break;
      case 20:
        _fetchFailedPayments(silent: true);
        break;
      default:
        break;
    }
  }

  @override
  void initState() {
    super.initState();
    _accountNameCtrl = TextEditingController(text: widget.user['name'] ?? '');
    _accountEmailCtrl = TextEditingController(text: widget.user['email'] ?? '');
    
    // Load per-admin permissions if not superadmin
    if (widget.user['role'] != 'superadmin' && widget.user['permissions'] != null) {
      final userPerms = Map<String, dynamic>.from(widget.user['permissions']);
      userPerms.forEach((key, value) {
        if (_adminPermissions.containsKey(key)) {
          _adminPermissions[key] = value == true;
        }
      });
    }

    // Fast Startup - Load essential dashboard configs and first tab immediately
    _fetchSettings();
    _fetchFinancialStats(silent: true);
    _fetchPerformanceAnalytics(silent: true);
    _fetchDispatchOrders(silent: true);
    _fetchCustomerOrders(silent: true);
    _initSocket();
    
    // SMART BACKGROUND SYNC - Every 15 seconds for active tab only (High FPS, zero lag, minimal resource footprint)
    _refreshTimer = Timer.periodic(const Duration(seconds: 15), (timer) {
      if (mounted) {
        _syncActiveTab();
      }
    });
  }

  @override
  void dispose() {
    _refreshTimer?.cancel();
    _socket?.disconnect();
    _socket?.dispose();
    _accountNameCtrl.dispose();
    _accountEmailCtrl.dispose();
    _accountPassCtrl.dispose();
    _adTaglineCtrl.dispose();
    _adHeadlineCtrl.dispose();
    _adSubtextCtrl.dispose();
    _adPromoCodeCtrl.dispose();
    _adDiscountTagCtrl.dispose();
    _adCtaTextCtrl.dispose();
    _adImageUrlCtrl.dispose();
    super.dispose();
  }



  Future<void> _fetchSubscriptionPlans({bool silent = false}) async {
    if (mounted && !silent) setState(() => _isPlansLoading = true);
    try {
      final plans = await SubscriptionService.getAllPlans(_headers);
      if (mounted) {
        setState(() {
          _subscriptionPlans = plans;
          _isPlansLoading = false;
        });
      }
    } catch (e) {
      if (mounted && !silent) setState(() => _isPlansLoading = false);
    }
  }

  void _initSocket() {
    try {
      final socketUrl = _baseUrl.replaceAll('/api/v1', '');
      _socket = io.io(socketUrl, io.OptionBuilder()
          .setTransports(['websocket'])
          .enableAutoConnect()
          .build());

      _socket!.onConnect((_) {
        debugPrint(' Admin Socket Connected');
        _socket!.emit('join_room', 'admin');
      });

      _socket!.on('orders_wiped', (_) {
        debugPrint('&& GLOBAL ORDERS WIPED: Clearing admin lists');
        // Legacy local sync cleared (No longer used)
        if (mounted) {
          setState(() {
            _customerOrders.clear();
            _customerOrderHistory.clear();
            _dispatchOrders.clear();
          });
        }
      });

      _socket!.on('update_rider_location', (data) {
        if (data != null && data is Map) {
          final rid = data['riderId']?.toString();
          if (rid != null && rid.isNotEmpty) {
            final lat = (data['lat'] as num?)?.toDouble() ?? 0.0;
            final lng = (data['lng'] as num?)?.toDouble() ?? 0.0;
            _liveRiders[rid] = {
              'lat': lat,
              'lng': lng,
              'lastUpdate': DateTime.now(),
              'name': data['riderName'] ?? 'Driver #$rid',
              'status': data['status'] ?? 'Active',
            };
            if (_tab == 6 && mounted) {
              if (!_hasInitialCenteredLiveTracking && lat != 0.0 && lng != 0.0) {
                _hasInitialCenteredLiveTracking = true;
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  try {
                    _liveTrackingMapController.move(LatLng(lat, lng), 15.5);
                  } catch (e) {
                    debugPrint('Live tracking map move error: $e');
                  }
                });
              }
              setState(() {});
            }
          }
        }
      });

      _socket!.on('vendor_status_update', (data) {
        debugPrint('& LIVE VENDOR STATUS UPDATE: $data');
        if (mounted) {
          setState(() {
            final vid = data['vendorId'];
            final isOpen = data['isOpen'];
            final lastOfflineAt = data['lastOfflineAt'];
            final lastOnlineAt = data['lastOnlineAt'];

            // Update vendors list
            final idx = _vendors.indexWhere((v) => v['_id'] == vid);
            if (idx != -1) {
              _vendors[idx]['isOpen'] = isOpen;
              if (lastOfflineAt != null) _vendors[idx]['lastOfflineAt'] = lastOfflineAt;
