  Future<void> _fetchAllVendors({bool silent = false}) async {
    if (mounted && !silent) setState(() => _isVendorsLoading = true);
    try {
      final response = await http.get(Uri.parse('$_baseUrl/admin/vendors'), headers: _headers);
      if (response.statusCode == 401) {
        if (mounted && !silent) widget.onLogout();
        return;
      }
      final data = jsonDecode(response.body);
      if (data['success'] == true) {
        if (mounted) {
          final now = DateTime.now();
          final list = List<Map<String, dynamic>>.from(data['data']);
          setState(() {
            _vendors = list;
            _offlineVendors = list.where((v) => (v['approvalStatus'] == 'approved' || v['status'] == 'approved') && v['isOpen'] != true && v['isLocked'] != true).toList();
            _expiringVendors = list.where((v) {
              if (v['approvalStatus'] != 'approved' && v['status'] != 'approved') return false;
              final subExp = v['subscriptionExpiry'] != null ? DateTime.tryParse(v['subscriptionExpiry'].toString()) : null;
              final trialExp = v['trialExpiry'] != null ? DateTime.tryParse(v['trialExpiry'].toString()) : null;
              final exp = subExp ?? trialExp;
              if (exp == null) return false;
              final diff = exp.difference(now).inDays;
              return diff <= 14;
            }).toList();
          });
        }
      }
    } catch (e) {
      debugPrint('Error fetching vendors: $e');
      if (mounted && !silent) {
        safeShowSnackBar(SnackBar(
          content: Text('Failed to load vendors: $e'),
          backgroundColor: Colors.red,
        ));
      }
    } finally {
      if (mounted && !silent) setState(() => _isVendorsLoading = false);
    }
  }

  Future<void> _fetchPendingVendors({bool silent = false}) async {
    if (mounted && !silent) setState(() => _isPendingLoading = true);
    try {
      final response = await http.get(Uri.parse('$_baseUrl/admin/vendors/pending'), headers: _headers);
      if (response.statusCode == 401) {
