  Future<void> _deleteVendor(String vendorId, String storeName) async {
    final confirm = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: Text('Delete Vendor / கடையை நீக்கு', style: GoogleFonts.outfit(fontWeight: FontWeight.w900, fontSize: 18)),
        content: Text(
          'Are you sure you want to permanently delete "$storeName"?\n\n"$storeName" கடையை நிரந்தரமாக நீக்க விரும்புகிறீர்களா? இந்நடவடிக்கையை மீட்டெடுக்க முடியாது.',
          style: GoogleFonts.outfit(fontSize: 14),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text('Cancel (ரத்து)', style: GoogleFonts.outfit(color: Colors.grey, fontWeight: FontWeight.w600)),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.red,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
            ),
            child: Text('Delete Permanently (நீக்கு)', style: GoogleFonts.outfit(color: Colors.white, fontWeight: FontWeight.bold)),
          ),
        ],
      ),
    );

    if (confirm == true) {
      try {
        final response = await http.delete(
          Uri.parse('$_baseUrl/admin/vendors/$vendorId'),
          headers: _headers,
        );
        final data = jsonDecode(response.body);
        if (data['success'] == true) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(SnackBar(
              content: Text('✅ Vendor "$storeName" deleted successfully!'),
              backgroundColor: Colors.green.shade700,
              behavior: SnackBarBehavior.floating,
            ));
          }
          setState(() {
            _selectedVendorIdx = 0;
          });
          _fetchPendingVendors();
          _fetchAllVendors();
        } else {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(SnackBar(
              content: Text('Failed: ${data['error']}'),
              backgroundColor: Colors.red,
              behavior: SnackBarBehavior.floating,
            ));
          }
        }
      } catch (e) {
        debugPrint('Error deleting vendor: $e');
      }
    }
  }

  Future<void> _fetchHeatmapData({bool silent = false}) async {
    if (mounted && !silent) setState(() => _isHeatmapLoading = true);
    try {
      final response = await http.get(Uri.parse('$_baseUrl/admin/heatmap'), headers: _headers).timeout(const Duration(seconds: 10));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data['success'] == true && data['data'] != null) {
          final orders = (data['data']['orders'] as List? ?? []);
          final riders = (data['data']['riders'] as List? ?? []);
          final vendors = (data['data']['vendors'] as List? ?? []);
          final insights = (data['data']['insights'] as Map<String, dynamic>? ?? {});
          final centerMap = data['data']['center'] as Map<String, dynamic>?;

          LatLng? center;
          if (centerMap != null && centerMap['lat'] != null && centerMap['lng'] != null) {
            final lat = (centerMap['lat'] as num).toDouble();
            final lng = (centerMap['lng'] as num).toDouble();
            if (lat != 0.0 || lng != 0.0) {
              center = LatLng(lat, lng);
            }
          }

          if (mounted) {
            setState(() {
              _heatmapOrdersList = orders.map((o) => Map<String, dynamic>.from(o as Map)).toList();
              _heatmapOrderPoints = orders.map((o) => LatLng((o['lat'] as num?)?.toDouble() ?? 0.0, (o['lng'] as num?)?.toDouble() ?? 0.0)).where((p) => p.latitude != 0.0 || p.longitude != 0.0).toList();
              _heatmapRiders = riders.map((r) => Map<String, dynamic>.from(r as Map)).toList();
              _heatmapVendors = vendors.map((v) => Map<String, dynamic>.from(v as Map)).toList();
              _marketInsights = insights;
              if (center != null) {
                _heatmapCenter = center;
              } else if (_heatmapOrderPoints.isNotEmpty) {
                _heatmapCenter = _heatmapOrderPoints.first;
              }
            });

            if (center != null) {
              WidgetsBinding.instance.addPostFrameCallback((_) {
                try {
                  _mapController.move(center!, 13.5);
                } catch (_) {}
              });
            }
          }
        }
      }
    } catch (e) {
      debugPrint('Heatmap Error: $e');
    } finally {
      if (mounted && !silent) setState(() => _isHeatmapLoading = false);
    }
  }

