      sortedVendors.sort((a, b) => ((b['totalSales'] as num?) ?? 0).compareTo((a['totalSales'] as num?) ?? 0));
    } else if (_vendorSortOption == 'orders_desc') {
      sortedVendors.sort((a, b) => ((b['orderCount'] as num?) ?? 0).compareTo((a['orderCount'] as num?) ?? 0));
