  void _exportFinancialReportCsv() {
    try {
      final buffer = StringBuffer();
      buffer.writeln('ORDER_ID,STORE_PARTNER,DRIVER_PARTNER,DATE_TIME,TOTAL_GMV,STORE_SHARE,PLATFORM_YIELD,DELIVERY_FEE,PAYMENT_METHOD,SETTLEMENT_STATUS');
      for (var tx in _vendorTransactions) {
        final id = tx['displayId'] ?? tx['orderId'] ?? '';
        final vendor = '"${tx['vendor'] ?? tx['vendorName'] ?? ''}"';
        final driver = '"${tx['driverName'] ?? ''}"';
        final date = '"${tx['date'] ?? ''}"';
        final gmv = tx['totalAmount'] ?? tx['amount'] ?? 0;
        final storeShare = tx['vendorEarnings'] ?? 0;
        final yieldV = tx['commission'] ?? 0;
        final deliveryFee = tx['deliveryCharge'] ?? 0;
        final method = tx['paymentMethod'] ?? 'UPI';
        final status = tx['status'] ?? tx['vendorPaymentStatus'] ?? 'Pending';
        buffer.writeln('$id,$vendor,$driver,$date,$gmv,$storeShare,$yieldV,$deliveryFee,$method,$status');
      }
      Clipboard.setData(ClipboardData(text: buffer.toString()));
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('Financial Audit Ledger exported & copied to clipboard in CSV format!', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
        backgroundColor: Color(0xFF059669),
      ));
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Export failed: $e'), backgroundColor: Colors.redAccent));
    }
  }

  String _extractVendorCity(Map<String, dynamic> v) {
    if (v['location'] is Map) {
      final locCity = v['location']['city']?.toString()?.trim();
      if (locCity != null && locCity.isNotEmpty && locCity.toLowerCase() != 'chennai') {
        return locCity;
      }
    }
    
    final directCity = v['city']?.toString()?.trim();
    if (directCity != null && directCity.isNotEmpty && directCity.toLowerCase() != 'chennai') {
      return directCity;
    }
    
    final fullAddr = ((v['location'] is Map && v['location']['formattedAddress'] != null && v['location']['formattedAddress'].toString().isNotEmpty)
        ? v['location']['formattedAddress'].toString()
        : (v['address']?.toString() ?? '')).trim();
        
    final addrLower = fullAddr.toLowerCase();
    if (addrLower.contains('erode')) return 'Erode';
    if (addrLower.contains('coimbatore') || addrLower.contains('kovai')) return 'Coimbatore';
    if (addrLower.contains('tirupur') || addrLower.contains('tiruppur')) return 'Tirupur';
    if (addrLower.contains('salem')) return 'Salem';
    if (addrLower.contains('madurai')) return 'Madurai';
    if (addrLower.contains('trichy') || addrLower.contains('tiruchirappalli')) return 'Trichy';
    if (addrLower.contains('bhavani')) return 'Bhavani';
    if (addrLower.contains('gobichettipalayam') || addrLower.contains('gobi')) return 'Gobichettipalayam';
    if (addrLower.contains('perundurai')) return 'Perundurai';
    if (addrLower.contains('sathyamangalam') || addrLower.contains('sathy')) return 'Sathyamangalam';
    if (addrLower.contains('namakkal')) return 'Namakkal';
    if (addrLower.contains('karur')) return 'Karur';
    if (addrLower.contains('dindigul')) return 'Dindigul';
    if (addrLower.contains('chennai')) return 'Chennai';

    if (fullAddr.isNotEmpty) {
      final parts = fullAddr.split(',').map((p) => p.trim()).where((p) => p.isNotEmpty).toList();
      if (parts.length >= 2) {
        for (int k = parts.length - 1; k >= 0; k--) {
          final clean = parts[k]
              .replaceAll(RegExp(r'\b\d{6}\b'), '')
              .replaceAll(RegExp(r'Tamil\s*Nadu', caseSensitive: false), '')
              .replaceAll(RegExp(r'India', caseSensitive: false), '')
              .replaceAll('-', '')
              .trim();
          if (clean.isNotEmpty && clean.length > 2) {
            return clean;
          }
        }
      }
      return parts.first;
    }

    if (v['location'] is Map && v['location']['city'] != null && v['location']['city'].toString().isNotEmpty) {
      return v['location']['city'].toString();
    }
    if (directCity != null && directCity.isNotEmpty) {
      return directCity;
    }

    return 'Erode';
  }

  Widget _cityBreakdown() {
    final cities = <String, double>{};
    for (var v in _vendors) {
      final city = _extractVendorCity(v);
      final revenue = double.tryParse(v['revenue']?.toString() ?? '0') ?? 0.0;
      cities[city] = (cities[city] ?? 0) + revenue;
    }
    if (cities.isEmpty) return const SizedBox(height: 100, child: Center(child: Text('No data')));
    final sorted = cities.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
    final max = sorted.first.value > 0 ? sorted.first.value : 1.0;
    final colors = [AdminColors.primaryIndigo, AdminColors.primaryIndigo, const Color(0xFF059669), const Color(0xFFD97706)];
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20),
          boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.04), blurRadius: 12)]),
      child: Column(children: sorted.asMap().entries.map((e) {
        final color = colors[e.key % colors.length];
        return Padding(padding: const EdgeInsets.symmetric(vertical: 8), child: Column(children: [
          Row(children: [
            Container(width: 10, height: 10, decoration: BoxDecoration(color: color, shape: BoxShape.circle)),
            const SizedBox(width: 8),
            Text(e.value.key, style: GoogleFonts.outfit(fontWeight: FontWeight.w700, fontSize: 13)),
            const Spacer(),
            Text('₹${NumberFormat('#,##,###').format(e.value.value)}',
                style: GoogleFonts.outfit(fontWeight: FontWeight.w900, color: color, fontSize: 14)),
          ]),
          const SizedBox(height: 6),
          ClipRRect(borderRadius: BorderRadius.circular(4), child: LinearProgressIndicator(
            value: e.value.value / max, backgroundColor: Colors.grey.shade100,
            valueColor: AlwaysStoppedAnimation<Color>(color), minHeight: 6,
          )),
        ]));
      }).toList()),
    );
  }

  Widget _categoryBreakdown() {
    final cats = <String, int>{};
    for (var v in _vendors) {
      final cat = v['category'] ?? 'General';
      final orders = int.tryParse(v['orders']?.toString() ?? '0') ?? 0;
      cats[cat] = (cats[cat] ?? 0) + orders;
    }
    final total = cats.values.fold(0, (s, c) => s + c);
    final icons = {'Grocery': '🛒', 'Bakery': '🥐', 'Medicine': '💊', 'Food': '🍔', 'Fruits & Vegetables': '🍎'};
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20),
          boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.04), blurRadius: 12)]),
      child: Column(children: cats.entries.map((e) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 6),
        child: Row(children: [
          Text(icons[e.key] ?? '&', style: const TextStyle(fontSize: 18)),
          const SizedBox(width: 10),
          Expanded(child: Text(e.key, style: GoogleFonts.outfit(fontWeight: FontWeight.w700))),
          Text('${e.value} orders', style: GoogleFonts.outfit(color: Colors.grey.shade500, fontSize: 12)),
          const SizedBox(width: 8),
          Text('${total > 0 ? (e.value / total * 100).toStringAsFixed(0) : 0}%',
              style: GoogleFonts.outfit(fontWeight: FontWeight.w900, color: AdminColors.primaryIndigo)),
        ]),
      )).toList()),
    );
  }

  Map<String, dynamic> _findFullVendorMap(Map<String, dynamic> v) {
    final id = (v['_id'] ?? v['id'] ?? '').toString();
    if (id.isNotEmpty) {
      final found = _vendors.firstWhere(
        (vend) => (vend['_id'] ?? vend['id'] ?? '').toString() == id,
        orElse: () => v,
      );
      return found;
    }
    return v;
  }

  int _findFullVendorIdx(Map<String, dynamic> v) {
    final id = (v['_id'] ?? v['id'] ?? '').toString();
    if (id.isNotEmpty) {
      final idx = _vendors.indexWhere(
        (vend) => (vend['_id'] ?? vend['id'] ?? '').toString() == id,
      );
      if (idx != -1) return idx;
    }
    return 0;
  }

