        isTrialExpired = true;
      }
    }

    final subExpiryStr = v['subscriptionExpiry']?.toString();
    DateTime? subExpiry;
    bool isSubExpired = false;
    if (subExpiryStr != null) {
      subExpiry = DateTime.tryParse(subExpiryStr)?.toLocal();
