                                final newPerms = Map<String, bool>.from(currentPerms.map((k, v) => MapEntry(k, v == true)));
                                newPerms[label] = val;
                                
                                // Direct sync
                                _updateAdminPerms(a['_id'], newPerms);
                                
                                // Update local state for immediate UI feedback in sheet
                                setS(() {
                                  a['permissions'] = newPerms;
                                });
                              },
                            ),
                          ],
