                                        if (ex.isNotEmpty) {
                                          activeHub['exclusionZones'] = ex.map((poly) {
                                            return poly.map((pt) => LatLng(pt.latitude + dLat, pt.longitude + dLng)).toList();
                                          }).toList();
                                        }
