                              suffixIcon: _supportSearchQuery.isNotEmpty
                                  ? IconButton(icon: const Icon(Icons.clear, size: 18), onPressed: () => setState(() { _supportSearchCtrl.clear(); _supportSearchQuery = ''; }))
                                  : null,
                              filled: true,
                              fillColor: const Color(0xFFF8FAFC),
