                            _supportStatusChip('IN PROGRESS', 'In Progress', const Color(0xFF2563EB), const Color(0xFFEFF6FF)),
                            _supportStatusChip('RESOLVED', 'Resolved', const Color(0xFF16A34A), const Color(0xFFF0FDF4)),
