                            final double subTotal = double.tryParse(order['subTotal']?.toString() ?? '0') ?? 0.0;
                            
                            double vendorPayout = subTotal > 0 ? subTotal : (totalAmount > 0 ? (totalAmount - deliveryFee - platformFee) : 0.0);
