class _PulsingDot extends StatefulWidget {
  const _PulsingDot({super.key});
  @override
  State<_PulsingDot> createState() => _PulsingDotState();
}

class _PulsingDotState extends State<_PulsingDot> with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this, duration: const Duration(seconds: 2))..repeat();
  }
  @override
  void dispose() { _controller.dispose(); super.dispose(); }
  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        return Container(
          width: 8, height: 8,
          decoration: BoxDecoration(
            color: Colors.green.shade400,
            shape: BoxShape.circle,
            boxShadow: [
              BoxShadow(color: Colors.green.shade400.withOpacity(1 - _controller.value), blurRadius: 8 * _controller.value, spreadRadius: 4 * _controller.value),
            ],
          ),
        );
      },
    );
  }
}

// ₹a ISOLATED BILLS HUB VIEW ₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹a₹aa
class OrderBillsHubView extends StatelessWidget {
  final List<Map<String, dynamic>> processedBills;
  final bool isLoading;
  final VoidCallback onRefresh;
  final Function(Map<String, dynamic>) onViewOrder;
  final Function(String, String) onPreviewImage;
  final String baseUrl;

  const OrderBillsHubView({
    super.key,
    required this.processedBills,
    required this.isLoading,
    required this.onRefresh,
    required this.onViewOrder,
    required this.onPreviewImage,
    required this.baseUrl,
  });

  @override
  Widget build(BuildContext context) {
    // Calculate total bills storage in MB and average size in KB
    double totalBillBytes = 0.0;
    for (final o in processedBills) {
      final num? b = o['billFileSizeBytes'];
      if (b != null && b > 0) {
        totalBillBytes += b.toDouble();
      } else {
        totalBillBytes += 250000.0; // standard approx 245 KB
      }
    }
    final String totalStorageStr = (totalBillBytes / (1024 * 1024)).toStringAsFixed(1) + ' MB';
    final String avgSizeStr = (totalBillBytes / (processedBills.isEmpty ? 1 : processedBills.length) / 1024).toStringAsFixed(0) + ' KB';

    return Container(
      color: const Color(0xFFF8FAFC),
      child: Column(
        children: [
          // Header
          Container(
            padding: const EdgeInsets.fromLTRB(40, 48, 40, 32),
            decoration: const BoxDecoration(
              color: Colors.white,
              border: Border(bottom: BorderSide(color: Color(0xFFE2E8F0))),
            ),
            child: Row(
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('BILL VERIFICATION & STORAGE', style: GoogleFonts.outfit(color: const Color(0xFF4F46E5), fontWeight: FontWeight.w900, fontSize: 12, letterSpacing: 2)),
                    const SizedBox(height: 4),
                    Text('Order Bills Hub', style: GoogleFonts.outfit(color: const Color(0xFF1E293B), fontWeight: FontWeight.w900, fontSize: 32)),
                  ],
                ),
                const Spacer(),
                if (isLoading)
                  const Padding(
                    padding: EdgeInsets.only(right: 24),
                    child: CircularProgressIndicator(strokeWidth: 2, color: Color(0xFF4F46E5)),
                  ),
                _statCardWidget('TOTAL BILLS', processedBills.length.toString(), Icons.receipt_long_rounded, const Color(0xFF4F46E5)),
                const SizedBox(width: 16),
                _statCardWidget('TOTAL STORAGE', totalStorageStr, Icons.cloud_done_rounded, const Color(0xFF059669)),
                const SizedBox(width: 16),
                _statCardWidget('AVG FILE SIZE', avgSizeStr, Icons.compress_rounded, const Color(0xFFD97706)),
                const SizedBox(width: 24),
                IconButton(
                  onPressed: onRefresh,
                  icon: const Icon(Icons.refresh_rounded, color: Color(0xFF4F46E5)),
                  style: IconButton.styleFrom(backgroundColor: const Color(0xFF4F46E5).withOpacity(0.1), padding: const EdgeInsets.all(12)),
                ),
              ],
            ),
          ),

          Expanded(
            child: (processedBills.isEmpty && !isLoading)
                ? _buildEmptyState()
                : GridView.builder(
                    padding: const EdgeInsets.all(40),
                    gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                      maxCrossAxisExtent: 400,
                      crossAxisSpacing: 24,
                      mainAxisSpacing: 24,
                      childAspectRatio: 0.80,
                    ),
                    itemCount: processedBills.length,
                    itemBuilder: (context, index) {
                      try {
                        return _SafeBillCard(
                          order: processedBills[index],
                          baseUrl: baseUrl,
                          onViewDetails: onViewOrder,
                          onPreviewImage: onPreviewImage,
                        );
                      } catch (e) {
                        return const SizedBox.shrink();
                      }
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _statCardWidget(String label, String value, IconData icon, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFFE2E8F0)),
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.02), blurRadius: 10, offset: const Offset(0, 4))],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(color: color.withOpacity(0.1), borderRadius: BorderRadius.circular(12)),
            child: Icon(icon, color: color, size: 20),
          ),
          const SizedBox(width: 14),
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(label, style: GoogleFonts.outfit(fontSize: 10, fontWeight: FontWeight.w800, color: Colors.grey.shade400, letterSpacing: 0.5)),
              Text(value, style: GoogleFonts.outfit(fontSize: 20, fontWeight: FontWeight.w900, color: const Color(0xFF1E293B))),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildEmptyState() {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.receipt_long_outlined, size: 80, color: Colors.grey.shade200),
          const SizedBox(height: 24),
          Text('No bills found yet', style: GoogleFonts.outfit(fontSize: 20, fontWeight: FontWeight.w900, color: Colors.grey.shade400)),
          const SizedBox(height: 8),
          Text('Uploaded bill photos will appear here automatically.', style: TextStyle(color: Colors.grey.shade400)),
        ],
      ),
    );
  }
}

class _SafeBillCard extends StatelessWidget {
  final Map<String, dynamic> order;
  final String baseUrl;
  final Function(Map<String, dynamic>) onViewDetails;
  final Function(String, String) onPreviewImage;

  const _SafeBillCard({
    required this.order,
    required this.baseUrl,
    required this.onViewDetails,
    required this.onPreviewImage,
  });

  @override
  Widget build(BuildContext context) {
    final billPath = order['billPhotoPath']?.toString() ?? '';
    final isLocal = billPath.contains(':\\');
    final billUrl = (billPath.startsWith('http') || isLocal) ? billPath : '${baseUrl.split('/api').first}${billPath.startsWith('/') ? '' : '/'}$billPath';
    final displayId = order['displayId']?.toString() ?? '#---';

    final rawFileSize = order['billFileSizeFormatted'] != null && order['billFileSizeFormatted'].toString().isNotEmpty
        ? order['billFileSizeFormatted'].toString()
        : ((order['billFileSizeBytes'] != null && (order['billFileSizeBytes'] as num) > 0)
            ? '${((order['billFileSizeBytes'] as num) / 1024).toStringAsFixed(1)} KB'
            : '245.0 KB');
    
    // Driver Safe Access
    String driverName = 'Unknown Driver';
    final driverData = order['driver'];
    if (driverData != null && driverData is Map) {
      driverName = driverData['name']?.toString() ?? 'Unknown Driver';
    }

    // Date Safe Access
    String dateStr = 'Unknown Time';
    final rawDate = order['billUploadedAt'];
    if (rawDate != null) {
      try {
        DateTime? dt;
        if (rawDate is String) dt = DateTime.tryParse(rawDate);
        else if (rawDate is num) dt = DateTime.fromMillisecondsSinceEpoch(rawDate.toInt());
        
        if (dt != null) {
          dateStr = '${dt.day}/${dt.month}/${dt.year} ${dt.hour}:${dt.minute.toString().padLeft(2, '0')}';
        }
      } catch (_) {}
    }

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: const Color(0xFFE2E8F0)),
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.02), blurRadius: 20, offset: const Offset(0, 8))],
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Stack(
              children: [
                Positioned.fill(
                  child: isLocal 
                    ? Image.file(
                        File(billPath),
                        fit: BoxFit.cover,
                        errorBuilder: (c, e, s) => Container(
                          color: const Color(0xFFF1F5F9),
                          child: const Icon(Icons.broken_image_outlined, color: Colors.grey, size: 32),
                        ),
                      )
                    : CachedNetworkImage(
                        imageUrl: billUrl,
                        fit: BoxFit.cover,
                        memCacheWidth: 600,
                        memCacheHeight: 600,
                        placeholder: (context, url) => Container(
                          color: const Color(0xFFF8FAFC),
                          child: const Center(child: CircularProgressIndicator(strokeWidth: 2, color: Color(0xFF4F46E5))),
                        ),
                        errorWidget: (context, url, error) => Container(
                          color: const Color(0xFFF1F5F9),
                          child: const Icon(Icons.broken_image_outlined, color: Colors.grey, size: 32),
                        ),
                      ),
                ),
                Positioned.fill(
                  child: Material(
                    color: Colors.transparent,
                    child: InkWell(
                      onTap: () => onPreviewImage(billUrl, 'Order Bill - $displayId ($rawFileSize)'),
                    ),
                  ),
                ),
                // Top Right Display ID Badge
                Positioned(
                  top: 12, right: 12,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                    decoration: BoxDecoration(color: Colors.black.withOpacity(0.75), borderRadius: BorderRadius.circular(10)),
                    child: Text(displayId, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 11)),
                  ),
                ),
                // Top Left File Size Badge
                Positioned(
                  top: 12, left: 12,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: const Color(0xFF0F172A).withOpacity(0.85),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: Colors.white24, width: 0.8),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Icon(Icons.sd_storage_rounded, color: Color(0xFF34D399), size: 11),
                        const SizedBox(width: 4),
                        Text(
                          rawFileSize,
                          style: GoogleFonts.outfit(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 10.5),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
