class _MapLabel extends StatelessWidget {
  final String label;
  final Color color;
  final IconData icon;
  final bool isPulsing;

  const _MapLabel({
    required this.label,
    required this.color,
    required this.icon,
    this.isPulsing = false,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
